method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0  // The input list must be non-empty
    ensures |result| == |numbers|  // The output list has the same length as the input list
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])  // Each element in result is the maximum up to that index
{
    var maxValue := numbers[0];
    var n := |numbers|;

    var res := new int[n];
    res[0] := maxValue;

    // Compute rolling max
    var i := 1;
    while i < n
        invariant 1 <= i <= n  // i is always within bounds
        invariant res[0..i] == [maxValue] + [Max(numbers[0..j+1]) | j := 0..i-1]  // The result so far is correct
    {
        if numbers[i] > maxValue {
            maxValue := numbers[i];
        }
        res[i] := maxValue;
        i := i + 1;
    }

    // Return the result
    result := res;
}
